// Read and validate template manifests — đọc và kiểm tra template manifest.
// Bounded manifest parsing and feature contracts.
use super::*;

#[derive(Debug, Deserialize)]
pub(in crate::scaffold::processor) struct TemplateManifest {
    #[serde(default)]
    tokens: Vec<TemplateToken>,
    pub(in crate::scaffold::processor) files: Vec<TemplateFile>,
}
/// These defaults are generated by compiled processors, not cached template archives.
/// Các mặc định này chạy processor thật; archive snapshot cũ không phải template layer.
pub(crate) fn has_builtin_scaffold_processor(layer: &str) -> bool {
    matches!(layer, "ai/python-agent" | "app/flutter" | "lib/rust")
}
pub(in crate::scaffold::processor) const MAX_TEMPLATE_MANIFEST_BYTES: u64 = 16 * 1024 * 1024;
/// Validate the exact manifest schema consumed by the materializer.
/// Fetch/cache phải nhận cùng contract với processor, không chỉ TOML hợp cú pháp.
pub(crate) fn validate_template_manifest(root: &Path) -> Result<()> {
    let _: TemplateManifest = toml::from_str(&read_template_manifest(root)?)?;
    Ok(())
}
pub(in crate::scaffold::processor) fn read_template_manifest(root: &Path) -> Result<String> {
    use std::io::Read;
    let path = checked_template_path(root, "template.toml")?;
    let mut bytes = Vec::new();
    std::fs::File::open(path)?
        .take(MAX_TEMPLATE_MANIFEST_BYTES + 1)
        .read_to_end(&mut bytes)?;
    if bytes.len() as u64 > MAX_TEMPLATE_MANIFEST_BYTES {
        return Err(crate::scaffold::error::template_manifest_too_large(
            MAX_TEMPLATE_MANIFEST_BYTES,
        ));
    }
    Ok(String::from_utf8(bytes)?)
}
impl TemplateManifest {
    pub(in crate::scaffold::processor) fn load(layer: &TemplateRoot) -> Result<Option<Self>> {
        if !layer.exists("template.toml") {
            if !layer.exists("sources") {
                return Ok(None);
            }
            return Err(crate::scaffold::error::template_manifest_missing(
                &layer.logical_rel(),
            ));
        }

        let contents = read_template_manifest(layer.path())?;
        let mut manifest: Self = toml::from_str(&contents)?;
        manifest.apply_root_token_contracts();
        Ok(Some(manifest))
    }

    fn apply_root_token_contracts(&mut self) {
        if self.tokens.is_empty() {
            return;
        }

        let root_tokens = self
            .tokens
            .iter()
            .map(|token| token.name.clone())
            .collect::<Vec<_>>();

        for file in &mut self.files {
            if file.required_context.is_empty() {
                file.required_context = root_tokens.clone();
            }
        }
    }
}
#[derive(Debug, Deserialize)]
struct TemplateToken {
    name: String,
}
#[derive(Debug, Deserialize)]
pub(in crate::scaffold::processor) struct TemplateFile {
    pub(in crate::scaffold::processor) source: String,
    pub(in crate::scaffold::processor) target: String,
    #[serde(default)]
    pub(in crate::scaffold::processor) required_context: Vec<String>,
    #[serde(default)]
    pub(in crate::scaffold::processor) include_features: Vec<String>,
    #[serde(default)]
    pub(in crate::scaffold::processor) exclude_features: Vec<String>,
}
impl TemplateFile {
    pub(in crate::scaffold::processor) fn is_cli_generated_container_asset(&self) -> bool {
        let target = self.target.replace('\\', "/");
        let normalized = target.trim_start_matches("./");
        let file_name = normalized
            .rsplit('/')
            .next()
            .unwrap_or(normalized)
            .to_ascii_lowercase();

        self.include_features.iter().any(|feature| {
            feature.eq_ignore_ascii_case("docker") || feature.eq_ignore_ascii_case("k8s")
        }) || matches!(
            file_name.as_str(),
            "dockerfile"
                | "containerfile"
                | ".dockerignore"
                | ".containerignore"
                | "docker-compose.yml"
                | "docker-compose.yaml"
                | "compose.yml"
                | "compose.yaml"
                | "mgc-container-entrypoint"
        ) || normalized == "k8s"
            || normalized.starts_with("k8s/")
            || normalized == "kubernetes"
            || normalized.starts_with("kubernetes/")
    }

    pub(in crate::scaffold::processor) fn is_enabled(
        &self,
        active_features: &HashSet<&str>,
    ) -> bool {
        self.include_features
            .iter()
            .all(|feature| active_features.contains(feature.as_str()))
            && self
                .exclude_features
                .iter()
                .all(|feature| !active_features.contains(feature.as_str()))
    }
}
